import Foundation

/// Why a clipboard change was not recorded.
public enum SkipReason: Sendable, Equatable {
    case historyOff
    case paused
    /// DocShot itself wrote this change (for example, copying an item back from history).
    case ownWrite
    /// A password manager or other app marked the content as concealed, transient or
    /// auto-generated.
    case marker(String)
    /// The app in front when the copy happened is excluded.
    case excludedApp(String)
    /// None of the pasteboard types is one history keeps.
    case unsupportedContent
    /// A single copy over the per-item limit.
    case tooLarge(byteSize: Int)
    /// Pinned items alone fill the storage cap, so nothing new fits.
    case storageFull
}

public enum RecordDecision: Sendable, Equatable {
    case record
    case skip(SkipReason)
}

/// What the watcher knows about one clipboard change before it reads any content.
public struct ClipboardChange: Sendable, Equatable {
    public let changeCount: Int
    public let types: [String]
    public let frontmostBundleID: String?

    public init(changeCount: Int, types: [String], frontmostBundleID: String?) {
        self.changeCount = changeCount
        self.types = types
        self.frontmostBundleID = frontmostBundleID
    }
}

/// Decides whether a clipboard change may be recorded at all (plan section 4.3). Runs before
/// the content is read, so a skipped change is never read.
public struct RecordingRules: Sendable, Equatable {
    /// Community pasteboard markers (nspasteboard.org) and 1Password's own marker.
    public static let skipMarkers: [String] = [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
        "com.agilebits.onepassword",
    ]

    /// Default excluded apps: Passwords, Keychain Access, Bitwarden and 1Password (8 and 7).
    public static let defaultExcludedBundleIDs: Set<String> = [
        "com.apple.Passwords",
        "com.apple.keychainaccess",
        "com.bitwarden.desktop",
        "com.1password.1password",
        "com.agilebits.onepassword7",
    ]

    /// Pasteboard types history keeps, in the order the app side should prefer them.
    public static let supportedTypes: [String] = [
        "public.file-url",
        "public.png",
        "public.tiff",
        "public.rtf",
        "public.utf8-plain-text",
        "com.apple.cocoa.pasteboard.color",
    ]

    public var excludedBundleIDs: Set<String>

    public init(excludedBundleIDs: Set<String> = RecordingRules.defaultExcludedBundleIDs) {
        self.excludedBundleIDs = excludedBundleIDs
    }

    /// - Parameters:
    ///   - ownWriteChangeCounts: change counts produced by DocShot's own pasteboard writes.
    public func decide(
        _ change: ClipboardChange,
        historyEnabled: Bool,
        paused: Bool,
        ownWriteChangeCounts: Set<Int>
    ) -> RecordDecision {
        guard historyEnabled else { return .skip(.historyOff) }
        guard !paused else { return .skip(.paused) }
        if ownWriteChangeCounts.contains(change.changeCount) {
            return .skip(.ownWrite)
        }
        if let marker = Self.skipMarkers.first(where: change.types.contains) {
            return .skip(.marker(marker))
        }
        if let app = change.frontmostBundleID, excludedBundleIDs.contains(app) {
            return .skip(.excludedApp(app))
        }
        guard change.types.contains(where: Self.supportedTypes.contains) else {
            return .skip(.unsupportedContent)
        }
        return .record
    }
}
